-- Ribbon TERRAIN as ONE continuous heightmap (§4, §15-2; ci-3yl, ci-da2, ci-wly,
-- REBUILT ci-oe83 as a SINGLE edge-pinned field, no more "three heightmaps slapped
-- together").
--
-- The ribbon is generated by the MAP-GEN itself, not by an on_chunk_generated script.
-- This module is the single source of truth for the tile layout AND the environmental
-- damage.
--
-- THE ONE FIELD (ci-oe83). There is exactly ONE continuous heightmap value H, a smooth
-- monotonic function of the perpendicular (sunward->nightward) coordinate `p`. It is:
--   * PINNED at the edges: H = 1 (the hot-lava extreme) at the sunward map edge (+half),
--     H = 0 (the smooth-ice extreme) at the nightward edge (-half). The two OCEANS are
--     just the outer regions where the pinned value sits in ocean range -- they EMERGE
--     from the field, they are never a fixed-width band stamped on top.
--   * CLAMPED through the middle: across the habitable band the value stays strictly
--     BELOW the hot-damage threshold and ABOVE the cold-damage threshold, so the middle
--     can never reach a lava or ice value -- no lava/ice pocket, no player-trapping ring.
--   * MONOTONIC: H rises steadily from the ice edge to the lava edge, so each damage
--     threshold is crossed exactly ONCE near its edge. You MUST cross that single belt
--     to reach either ocean; there is no non-damaging corridor around it.
--
-- TILE + DAMAGE ARE BOTH A FUNCTION OF THE FIELD VALUE (ci-oe83):
--   * TILE (art): value in the top band -> hot-lava; descending value -> the hot crust,
--     the ash middle, the dust/snow, down to smooth-ice at the bottom. A single ordered
--     ramp (M.VALUE_RAMP) maps H -> tile, so the whole planet is one seamless surface
--     with no band boundary. A boundary wiggle + per-tile speckle make the contours
--     organic; the oceans radiate inward as concentric value contours. The SAFE HOT SLOPE
--     is the one place the ramp forks: two texture families (cracks / folds) cover that
--     one value segment and converge again on ash-dark (ci-72bw, M.FOLDS_RAMP).
--   * DAMAGE (lethal ground): value >= HOT_DMG -> heat (scaling with how far above), value
--     <= COLD_DMG -> cold, in between -> SAFE. Because the field is monotonic + clamped,
--     the damage is confined to two contiguous EDGE BELTS with a guaranteed safe middle
--     band down the whole long axis; the two belts never touch. Damage keys off the FIELD
--     VALUE (i.e. the perpendicular position), NOT the tile-type -- a cosmetic hot-looking
--     tile scattered in the middle does ZERO damage, and there is no non-damaging tile
--     path to either ocean at any elevation. (This is the ci-oe83 fix: ci-4jl keyed damage
--     per-tile, so a high-elevation ridge of non-damaging tiles could reach the lava.)
--
-- WIDTHS. Each zone width is a mod setting (settings.lua); the TOTAL is the SUM. Defaults
-- sum to 800 with the hot side equal to the cold side, so the 120-wide MIDDLE straddles
-- the origin (spawn). The ZONES are the positional geometry the field anchors + the
-- resource banding read; the field itself is derived from those anchors, so changing a
-- width moves the field with it.
--
-- WALKABILITY is per-TILE: only the two lava tiles are impassable (molten fluid); every
-- other tile (including smooth-ice) is walkable ground. The smooth-ice ocean is walkable
-- (you can run on it, it just freezes you by belt position).
--
-- NO-PAVE HAZARD TILES (ci-wly, closes ci-8vu): you cannot pave atop M.NO_PAVE (the two
-- lava tiles + the hottest crust + the two iciest tiles); scripts/no-paving.lua reverts
-- any tile built on one on the cindra surface.
--
-- The world is finite PERPENDICULAR via the map-gen's own `width`/`height`.
--
-- PURE where it counts: the field, the value->tile + value->damage maps, the zone table,
-- band geometry, the damage bounds and the probability/mask emitters are plain
-- string/table logic (no game.* / prototypes.*), unit-testable off the game
-- (unit-tests/test_terrain.lua). tests/test_worldgen + tests/test_heightmap prove it
-- generates as specified on a live surface.

local axis = require("scripts.axis")

local M = {}

-- ---------------------------------------------------------------------------
-- The ordered Cindra tile ZONES, HOT (west, +perp) -> COLD (east, -perp). This is the
-- POSITIONAL geometry (band widths, damage/ocean flags) the field anchors + the resource
-- banding read. Fields:
--   role     stable key for geometry helpers, settings + resource banding.
--   width    default band width in tiles (the mod-setting default).
--   setting  the per-zone width mod-setting name (settings.lua).
--   ocean    true => the region's OCEAN (the field's pinned extreme at that edge).
--   wall     true => a pure impassable lava wall (the hot ocean).
--   damage   "heat" | "cold" | nil: the environmental damage this BAND marks
--            (positional descriptor; the field crosses its damage threshold here).
-- ---------------------------------------------------------------------------
M.ZONES = {
  { role = "hot_ocean",  width = 200, setting = "cindra-zone-width-hot-ocean",
    ocean = true, wall = true, damage = "heat" },
  { role = "hot_inner",  width = 70,  setting = "cindra-zone-width-hot-inner",
    damage = "heat" },
  { role = "hot_outer",  width = 70,  setting = "cindra-zone-width-hot-outer" },
  { role = "middle",     width = 120, setting = "cindra-zone-width-middle" },
  { role = "cold_outer", width = 70,  setting = "cindra-zone-width-cold-outer" },
  { role = "cold_inner", width = 70,  setting = "cindra-zone-width-cold-inner",
    damage = "cold" },
  { role = "cold_ocean", width = 200, setting = "cindra-zone-width-cold-ocean",
    ocean = true, damage = "cold" },
}

-- The index of the wide safe MIDDLE band (spawn).
M.BUILDING_ROLE = "middle"
local BUILDING_INDEX
for i, z in ipairs(M.ZONES) do
  if z.role == M.BUILDING_ROLE then BUILDING_INDEX = i end
end

-- The cindra-* tile name for a vanilla clone source (deterministic prefix).
local function cindra_name(vanilla) return "cindra-" .. vanilla end
M.cindra_name = cindra_name

-- ---------------------------------------------------------------------------
-- THE ONE HEIGHTMAP FIELD (ci-oe83).
--
-- H is a normalised heat value in [0, 1]: 1 = the hot-lava ocean extreme, 0 = the
-- smooth-ice ocean extreme, ~0.5 = the temperate middle. The damage thresholds partition
-- it: H >= HOT_DMG is heat-lethal, H <= COLD_DMG is cold-lethal, strictly between is safe.
-- ---------------------------------------------------------------------------
M.HOT_DMG  = 0.70 -- H at/above this is heat-lethal (the hot belt inner edge)
M.COLD_DMG = 0.30 -- H at/below this is cold-lethal (the cold belt inner edge)

-- The FIXED field values pinned at each geometric anchor (a boundary condition). The
-- anchor POSITIONS come from the live zone geometry (M.field_anchors), so the field
-- tracks the widths; only the VALUES are constants here. Monotonic: edge extremes, the
-- damage thresholds at the belt edges, gentle middle.
M.FIELD_H = {
  edge   = 1.00, -- pinned lava extreme at the sunward edge (+half)
  ocean  = 0.94, -- at the ocean inner edge: solidly in the lava-hot band
  dmg    = M.HOT_DMG, -- at the hot damage boundary
  middle = 0.56, -- at the middle's hot edge (ash)
}
-- Cold-side mirror values (1 - hot value).
local function mirror(h) return 1 - h end

-- The ordered VALUE RAMP: hottest tile first, `lo` is the tile's LOWER H threshold (its
-- upper threshold is the previous tile's `lo`). value -> tile is "the first tile whose lo
-- the value clears". The two ends are the ocean cores. This single ramp spans the WHOLE
-- planet -- there is no separate hot/cold ring table.
local RAMP_BIG = 1e9
M.VALUE_RAMP = {
  { vanilla = "lava-hot",                   lo = 0.90 }, -- hot-lava ocean core (heat)
  { vanilla = "lava",                       lo = 0.82 }, -- molten body (heat)
  { vanilla = "volcanic-smooth-stone-warm", lo = 0.76 }, -- warm crust (heat)
  { vanilla = "volcanic-cracks-hot",        lo = M.HOT_DMG }, -- glowing crust; HOT_DMG edge
  -- The safe hot SLOPE (below HOT_DMG, above the ash middle) is the CRACKS family: the
  -- main line, and the segment the ci-72bw FOLDS family branches against.
  { vanilla = "volcanic-cracks-warm",       lo = 0.655, branch = "cracks" }, -- warm cracks (SAFE, hot look)
  { vanilla = "volcanic-cracks",            lo = 0.62,  branch = "cracks" }, -- cool cracks
  { vanilla = "volcanic-smooth-stone",      lo = 0.585, branch = "cracks" }, -- cool stone
  { vanilla = "volcanic-ash-dark",          lo = 0.525 }, -- dark ash (middle); the CONVERGENCE
  { vanilla = "volcanic-ash-flats",         lo = 0.465 }, -- ash flats (middle centre)
  { vanilla = "volcanic-ash-light",         lo = 0.42 },  -- light ash (middle)
  { vanilla = "dust-flat",                  lo = 0.395 }, -- dust (SAFE, cold look)
  { vanilla = "dust-crests",                lo = 0.37 },
  { vanilla = "dust-lumpy",                 lo = 0.345 },
  { vanilla = "dust-patchy",                lo = 0.32 },
  { vanilla = "snow-flat",                  lo = M.COLD_DMG }, -- snow; COLD_DMG edge (SAFE)
  { vanilla = "snow-crests",                lo = 0.25 }, -- snow (cold)
  { vanilla = "snow-lumpy",                 lo = 0.20 },
  { vanilla = "snow-patchy",                lo = 0.16 },
  { vanilla = "ice-rough",                  lo = 0.10 }, -- rough ice (cold)
  { vanilla = "ice-smooth",                 lo = -RAMP_BIG }, -- smooth-ice ocean core (cold)
}

-- ---------------------------------------------------------------------------
-- THE HOT-SIDE FOLDS BRANCH (ci-72bw).
--
-- The safe hot SLOPE (the value segment strictly between HOT_DMG and the ash middle) has
-- TWO texture families instead of one. Both cover the SAME value segment and both
-- CONVERGE on volcanic-ash-dark below it -- only the art differs:
--   * CRACKS (the ci-wly main line): cracks-warm -> cracks -> smooth-stone.
--   * FOLDS  (this branch):          folds-warm -> folds -> folds-flat -> ash-cracks ->
--                                    pumice-stones.
-- Which family paints a given point is decided by a LOW-FREQUENCY branch noise: broad
-- regions of the hot slope read folded/pumice, the rest read cracked, and the two
-- interpenetrate where the noise crosses zero (so the family boundary is organic, not a
-- seam). Because the families share the segment, the damage model is untouched -- a folds
-- tile is exactly as (non-)lethal as the cracks tile at the same field value.
-- ---------------------------------------------------------------------------

-- The BRANCH SPAN = the value segment the cracks family owns in the ramp (derived, so the
-- folds family tracks any future retune of the main line): the top is the hi of the first
-- cracks member (== HOT_DMG), the bottom the lo of the last (== ash-dark's hi).
M.BRANCH_SPAN = (function()
  local hi, lo
  local prev_lo = RAMP_BIG
  for _, r in ipairs(M.VALUE_RAMP) do
    if r.branch == "cracks" then
      if hi == nil then hi = prev_lo end
      lo = r.lo
    end
    prev_lo = r.lo
  end
  return { lo = lo, hi = hi }
end)()

-- The vanilla clone sources of the FOLDS family, hottest first. They split the branch span
-- into equal sub-bands, so the family spans exactly the same values as the cracks family.
M.FOLDS_FAMILY = {
  "volcanic-folds-warm",    -- the folds counterpart of cracks-warm (same low/zero heat)
  "volcanic-folds",
  "volcanic-folds-flat",
  "volcanic-ash-cracks",
  "volcanic-pumice-stones", -- thins into ash-dark: the shared convergence
}

-- The folds family as a value ramp (same shape as M.VALUE_RAMP: `lo` is the lower bound).
M.FOLDS_RAMP = (function()
  local n = #M.FOLDS_FAMILY
  local step = (M.BRANCH_SPAN.hi - M.BRANCH_SPAN.lo) / n
  local out = {}
  for i, vanilla in ipairs(M.FOLDS_FAMILY) do
    out[i] = { vanilla = vanilla, lo = M.BRANCH_SPAN.lo + (n - i) * step, branch = "folds" }
  end
  out[n].lo = M.BRANCH_SPAN.lo -- pin the bottom exactly onto the convergence value
  return out
end)()

-- The folds family is registered into the tile order directly after this main-line tile,
-- so M.TILES still reads hot -> cold.
M.BRANCH_AFTER = "volcanic-cracks-hot"

-- SOIL patches: a mini ring model on a low-frequency PATCH field, confined to the middle
-- band. soil-dark at a patch centre, ringed by soil-light, then ash-soil, blending back
-- to the ash mix. These are an OVERLAY (not in the value ramp); they win only inside a
-- patch and only in the middle, for looks (they carry no damage of their own).
M.SOIL_RING_ORDER = {
  { vanilla = "volcanic-soil-dark",  lo = 20 }, -- patch centre (highest patch elevation)
  { vanilla = "volcanic-soil-light", lo = 14 }, -- ring around the dark core
  { vanilla = "volcanic-ash-soil",   lo = 8 },  -- outer ring, blends to the ash mix
}

-- The NO-PAVE hazard set (ci-wly): the hottest / iciest hazards. Blocking paving here
-- keeps the lethal ground lethal and closes the ci-8vu lava-pump exploit.
M.NO_PAVE_VANILLA = {
  "lava-hot", "lava", "volcanic-smooth-stone-warm", "volcanic-cracks-hot",
  "ice-smooth", "ice-rough",
}

-- Impassable tiles: only the two lava tiles (molten fluid). smooth-ice is WALKABLE.
local IMPASSABLE = { ["lava-hot"] = true, ["lava"] = true }

-- The MOLTEN FLOOR: the lowest field value the ramp paints as MOLTEN (an impassable lava
-- tile). At or above it the ground is liquid rock, so nothing can lie ON it -- any ground
-- clutter (the rock / crater decals, scripts/decorative-field.lua) has to stay strictly
-- below this value or it floats on the lava. Derived from the ramp + the impassable set,
-- so retuning either moves it.
M.MOLTEN_FLOOR = (function()
  local lo
  for _, r in ipairs(M.VALUE_RAMP) do
    if IMPASSABLE[r.vanilla] and (lo == nil or r.lo < lo) then lo = r.lo end
  end
  return lo
end)()

M.NO_PAVE = {}
for _, vanilla in ipairs(M.NO_PAVE_VANILLA) do M.NO_PAVE[cindra_name(vanilla)] = true end

-- True if a tile is in the NO-PAVE hazard set (scripts/no-paving.lua reads this).
function M.is_no_pave(name) return M.NO_PAVE[name] == true end

-- ---------------------------------------------------------------------------
-- value -> tile and value -> damage (PURE, the heart of the ci-oe83 model).
-- ---------------------------------------------------------------------------

-- The cindra tile a field value H falls in (the first ramp tile whose lo it clears).
-- `family` selects the hot-slope texture family (ci-72bw): the default (nil / "cracks") is
-- the main line; "folds" swaps in the folds family INSIDE the branch span only -- outside
-- it (the oceans, the crust, the ash middle, the whole cold side) both families are the
-- same ramp, which is exactly what "the two families converge on ash-dark" means.
function M.value_tile(H, family)
  if family == "folds" and H >= M.BRANCH_SPAN.lo and H < M.BRANCH_SPAN.hi then
    for _, r in ipairs(M.FOLDS_RAMP) do
      if H >= r.lo then return cindra_name(r.vanilla) end
    end
  end
  for _, r in ipairs(M.VALUE_RAMP) do
    if H >= r.lo then return cindra_name(r.vanilla) end
  end
  return nil
end

-- The environmental damage a field value H inflicts: (intensity 0..1, kind) where kind is
-- "heat" for H >= HOT_DMG, "cold" for H <= COLD_DMG, and (0, nil) for the safe middle.
-- Intensity ramps from 0 at the threshold to 1 at the pinned extreme -> the depth ramp.
function M.value_damage(H)
  -- The thresholds are inclusive on the damaging side (intensity 0 exactly at the edge);
  -- a tiny tolerance keeps the boundary robust to piecewise-linear float error.
  local eps = 1e-9
  if H >= M.HOT_DMG - eps then
    local t = (H - M.HOT_DMG) / (1 - M.HOT_DMG)
    if t < 0 then t = 0 elseif t > 1 then t = 1 end
    return t, "heat"
  elseif H <= M.COLD_DMG + eps then
    local t = (M.COLD_DMG - H) / M.COLD_DMG
    if t < 0 then t = 0 elseif t > 1 then t = 1 end
    return t, "cold"
  end
  return 0, nil
end

-- ---------------------------------------------------------------------------
-- Zone widths + band geometry (PURE). Unchanged from ci-wly -- this is the positional
-- skeleton the field anchors + the resource banding read.
-- ---------------------------------------------------------------------------
function M.widths(cfg)
  cfg = cfg or {}
  local s = settings and settings.startup
  local out = {}
  for i, z in ipairs(M.ZONES) do
    local w = cfg[z.role]
    if w == nil and s and s[z.setting] then w = s[z.setting].value end
    if w == nil then w = z.width end
    out[i] = w
  end
  return out
end

-- The signed perpendicular band [lo, hi] (sunward-positive p, hot = high p) per zone,
-- centred on the origin (hot edge +TOTAL/2). Returns (bands, total).
function M.bands(cfg)
  local w = M.widths(cfg)
  local total = 0
  for _, v in ipairs(w) do total = total + v end
  local bands = {}
  local p = total / 2
  for i = 1, #w do
    bands[i] = { lo = p - w[i], hi = p }
    p = p - w[i]
  end
  return bands, total
end

function M.role_band(role, cfg)
  local bands = M.bands(cfg)
  for i, z in ipairs(M.ZONES) do
    if z.role == role then return bands[i] end
  end
  return nil
end

-- The perpendicular band spanned by a set of regions = the union of their zone bands.
local function region_band(roles, cfg)
  local bands = M.bands(cfg)
  local lo, hi
  for i, z in ipairs(M.ZONES) do
    if roles[z.role] then
      if lo == nil or bands[i].lo < lo then lo = bands[i].lo end
      if hi == nil or bands[i].hi > hi then hi = bands[i].hi end
    end
  end
  return { lo = lo, hi = hi }
end

-- The perpendicular band spanned by the HOT side (hot ocean + inner + outer) and the COLD
-- side (mirror). Kept for the decal / rock / art helpers that band on the hot/cold half.
function M.hot_region(cfg) return region_band({ hot_ocean = true, hot_inner = true }, cfg) end
function M.cold_region(cfg) return region_band({ cold_ocean = true, cold_inner = true }, cfg) end

-- The perp-axis boundaries scripts/resource-field.lua bands resources against.
function M.resource_bounds(cfg)
  local bands = M.bands(cfg)
  local b = bands[BUILDING_INDEX]
  local hot_edge = b.hi
  for i = BUILDING_INDEX - 1, 1, -1 do
    if not M.ZONES[i].wall then hot_edge = bands[i].hi else break end
  end
  return {
    building_half = b.hi,
    building_lo = b.lo,
    hot_edge = hot_edge,
    cold_edge = bands[#bands].lo,
  }
end

-- The perpendicular band spanned by the VOLCANIC rocky zones (hot inner + hot outer),
-- where burned volcanic rocks scatter. Excludes the lava ocean, middle and cold side.
M.CLIFF_ROLES = { "hot_inner", "hot_outer" }
function M.cliff_band(cfg)
  local lo, hi
  for _, role in ipairs(M.CLIFF_ROLES) do
    local b = M.role_band(role, cfg)
    if b then
      if lo == nil or b.lo < lo then lo = b.lo end
      if hi == nil or b.hi > hi then hi = b.hi end
    end
  end
  return { lo = lo, hi = hi }
end

-- The positional DAMAGE bounds (band edges where the damaging tiles live). hot_from is the
-- inner (middle-ward) edge of the heat belt, cold_from the inner edge of the cold belt.
-- The field crosses HOT_DMG at hot_from and COLD_DMG at cold_from by construction.
function M.damage_bounds(cfg)
  local bands = M.bands(cfg)
  local hot_from, cold_from
  for i, z in ipairs(M.ZONES) do
    if z.damage == "heat" then
      if hot_from == nil or bands[i].lo < hot_from then hot_from = bands[i].lo end
    elseif z.damage == "cold" then
      if cold_from == nil or bands[i].hi > cold_from then cold_from = bands[i].hi end
    end
  end
  return { hot_from = hot_from, cold_from = cold_from }
end

-- ---------------------------------------------------------------------------
-- THE FIELD, as a function of perpendicular position (PURE).
-- ---------------------------------------------------------------------------

-- The field ANCHORS (position, H) for the live geometry, sorted COLD->HOT (ascending p).
-- Positions come from the zone bands (edges, ocean inner edges, damage boundaries, middle
-- edges); the H values are the fixed constants in M.FIELD_H. A monotonic piecewise-linear
-- ramp through these anchors IS the field.
function M.field_anchors(cfg)
  local bands, total = M.bands(cfg)
  local half = total / 2
  local db = M.damage_bounds(cfg)
  local mid = bands[BUILDING_INDEX]
  local hot_ocean_lo = bands[1].lo      -- hot ocean inner edge
  local cold_ocean_hi = bands[#bands].hi -- cold ocean inner edge
  local H = M.FIELD_H
  return {
    { p = -half,        h = mirror(H.edge) },
    { p = cold_ocean_hi, h = mirror(H.ocean) },
    { p = db.cold_from, h = mirror(H.dmg) },
    { p = mid.lo,       h = mirror(H.middle) },
    { p = mid.hi,       h = H.middle },
    { p = db.hot_from,  h = H.dmg },
    { p = hot_ocean_lo, h = H.ocean },
    { p = half,         h = H.edge },
  }
end

-- Piecewise-linear interpolation of the field at perpendicular position `p` over a sorted
-- (ascending p) anchor list; flat beyond the ends (the pinned ocean plateaus). Clamped to
-- [0, 1]. This is the single source of truth for "how hot is it here".
local function pwl(p, anchors)
  if p <= anchors[1].p then return anchors[1].h end
  local n = #anchors
  if p >= anchors[n].p then return anchors[n].h end
  for i = 2, n do
    local a, b = anchors[i - 1], anchors[i]
    if p <= b.p then
      local f = (p - a.p) / (b.p - a.p)
      local h = a.h + (b.h - a.h) * f
      if h < 0 then h = 0 elseif h > 1 then h = 1 end
      return h
    end
  end
  return anchors[n].h
end

-- The field value H at perpendicular position `p` (0 = cold extreme .. 1 = hot extreme).
function M.field(p, cfg)
  return pwl(p, M.field_anchors(cfg))
end

-- The INVERSE of M.field: the perpendicular position where the field reaches value `h`.
-- The field is monotonic ascending in p, so that crossing is UNIQUE (the property the whole
-- ci-oe83 model rests on) and this is well defined; values at/past the pinned extremes
-- clamp to the map edges.
--
-- This is how a system that must land ON a particular tile family turns a TILE boundary in
-- the value ramp into the WORLD position of that tile's contour. A zone band edge is NOT a
-- tile boundary: with the default widths the molten contour (H = MOLTEN_FLOOR) sits ~35
-- tiles INSIDE the hot-ocean band, so gating ground clutter on the band edge would still
-- drop it on lava (that was the ci-mk5y decal bug). Gate on the crossing instead.
function M.field_crossing(h, cfg)
  local anchors = M.field_anchors(cfg)
  local n = #anchors
  if h <= anchors[1].h then return anchors[1].p end
  if h >= anchors[n].h then return anchors[n].p end
  for i = 2, n do
    local a, b = anchors[i - 1], anchors[i]
    if h <= b.h then
      if b.h == a.h then return a.p end
      return a.p + (b.p - a.p) * (h - a.h) / (b.h - a.h)
    end
  end
  return anchors[n].p
end

-- The environmental damage (intensity, kind) at perpendicular position `p`: the value
-- damage of the field there. Damage follows the FIELD VALUE, i.e. the position -- keyed to
-- neither tile-type nor a raw coordinate band. This is what the runtime sweep reads.
function M.field_damage(p, cfg)
  return M.value_damage(M.field(p, cfg))
end

-- The damage KIND ("heat"/"cold"/nil) at perpendicular position `p` -- the field-derived
-- classifier the feedback tint + resource keep-back read. Equal to the field crossing at
-- the damage bounds by construction.
function M.lethal_at(p, cfg)
  local _, kind = M.field_damage(p, cfg)
  return kind
end

-- ---------------------------------------------------------------------------
-- The concrete TILES (deduplicated), ordered hot -> cold, + map colours.
-- ---------------------------------------------------------------------------

-- A hot -> cold map-view colour ramp (ci-4h7): reds sunward, a dark ash belt at the
-- middle, pale cyan/frost nightward. `t` is the normalised gradient position (0 hottest,
-- 1 coldest).
--
-- THIS TABLE IS THE PLANET'S ONE PALETTE (ci-4qyj). The from-space art no longer keeps a
-- hand-copied twin of it: scripts/terrain_ramp.py READS this table (plus M.ZONES,
-- M.FIELD_H and M.VALUE_RAMP) out of this file and replays the same
-- position -> value -> tile -> colour chain, so the orbital globe and the star-map sprite
-- are painted with the ground you actually land on. Change a stop here and the space art
-- follows on the next render; unit-tests/test_terrain_ramp_lockstep.py runs both models
-- and fails if they ever disagree.
M.COLOR_STOPS = {
  { 0.00, { 0.98, 0.42, 0.06 } }, -- lava, orange-red
  { 0.18, { 0.80, 0.30, 0.10 } }, -- molten crust
  { 0.34, { 0.45, 0.32, 0.24 } }, -- warm volcanic brown (fire -> middle)
  { 0.46, { 0.243, 0.165, 0.125 } }, -- dark volcanic-ash middle #3E2A20
  { 0.54, { 0.255, 0.196, 0.157 } }, -- ash middle #41322A
  { 0.66, { 0.42, 0.42, 0.44 } }, -- cooling dust-grey (middle -> ice)
  { 0.80, { 0.66, 0.82, 0.88 } }, -- pale frost
  { 1.00, { 0.82, 0.95, 1.00 } }, -- icy white-blue
}
local COLOR_STOPS = M.COLOR_STOPS
local function ramp_color(t)
  if t <= COLOR_STOPS[1][1] then return COLOR_STOPS[1][2] end
  for i = 2, #COLOR_STOPS do
    local a, b = COLOR_STOPS[i - 1], COLOR_STOPS[i]
    if t <= b[1] then
      local f = (t - a[1]) / (b[1] - a[1])
      local ca, cb = a[2], b[2]
      return { ca[1] + (cb[1] - ca[1]) * f, ca[2] + (cb[2] - ca[2]) * f, ca[3] + (cb[3] - ca[3]) * f }
    end
  end
  return COLOR_STOPS[#COLOR_STOPS][2]
end

M.TILES = {}
local TILE_BY_NAME = {}     -- cindra name -> tile entry
local VALUE_BAND = {}       -- cindra name -> { lo, hi } value band (ramp tiles only)
local SOIL_RING_BAND = {}   -- cindra name -> { lo, hi } soil patch band
local GRADIENT_POS = {}     -- cindra name -> normalised 0..1 hot->cold position
local TILE_BRANCH = {}      -- cindra name -> "cracks" | "folds" (hot-slope family, ci-72bw)

do
  local order = {}
  local function register(vanilla, gradient_pos)
    local name = cindra_name(vanilla)
    if not TILE_BY_NAME[name] then
      local entry = { name = name, clone_from = vanilla, walkable = not IMPASSABLE[vanilla] }
      TILE_BY_NAME[name] = entry
      order[#order + 1] = entry
      GRADIENT_POS[name] = gradient_pos
    end
    return name
  end

  -- The value ramp: one continuous hot->cold sequence, gradient 0 (lava-hot) -> 1 (ice).
  local nr = #M.VALUE_RAMP
  -- The fractional ramp position of a value, so a FOLDS tile takes the map colour of the
  -- main-line tile it sits alongside (the two families read the same on the map view).
  local function gradient_for_value(H)
    local prev_lo = RAMP_BIG
    for i, r in ipairs(M.VALUE_RAMP) do
      if H >= r.lo then
        local f = (prev_lo <= r.lo) and 0 or ((prev_lo - H) / (prev_lo - r.lo))
        if f < 0 then f = 0 elseif f > 1 then f = 1 end
        return (i - 1 + f) / (nr - 1)
      end
      prev_lo = r.lo
    end
    return 1
  end

  for i, r in ipairs(M.VALUE_RAMP) do
    local name = register(r.vanilla, (i - 1) / (nr - 1))
    VALUE_BAND[name] = { lo = r.lo }
    if r.branch then TILE_BRANCH[name] = r.branch end
    -- The FOLDS family (ci-72bw) is registered inline so M.TILES stays hot -> cold.
    if r.vanilla == M.BRANCH_AFTER then
      local prev_hi = M.BRANCH_SPAN.hi
      for _, f in ipairs(M.FOLDS_RAMP) do
        local fname = register(f.vanilla, gradient_for_value((f.lo + prev_hi) / 2))
        VALUE_BAND[fname] = { lo = f.lo, hi = prev_hi }
        TILE_BRANCH[fname] = f.branch
        prev_hi = f.lo
      end
    end
  end
  -- Fill in each MAIN-LINE ramp tile's upper bound (the previous tile's lo). The folds
  -- family already carries its own bands (they overlay the same span).
  do
    local prev_hi = RAMP_BIG
    for _, r in ipairs(M.VALUE_RAMP) do
      VALUE_BAND[cindra_name(r.vanilla)].hi = prev_hi
      prev_hi = r.lo
    end
  end

  -- Soil overlay tiles (middle only): gradient ~0.5 (they sit in the ash middle).
  do
    local prev_hi = RAMP_BIG
    for _, r in ipairs(M.SOIL_RING_ORDER) do
      local name = register(r.vanilla, 0.50)
      SOIL_RING_BAND[name] = { lo = r.lo, hi = prev_hi }
      prev_hi = r.lo
    end
  end

  for _, entry in ipairs(order) do entry.map_color = ramp_color(GRADIENT_POS[entry.name] or 0.5) end
  M.TILES = order
end

-- Single-source-of-truth cross-checks.
for name in pairs(M.NO_PAVE) do
  if not TILE_BY_NAME[name] then error("terrain: no-pave tile " .. name .. " is not a registered tile") end
end

function M.map_color(name)
  local t = TILE_BY_NAME[name]
  return t and t.map_color or nil
end

-- The hot-slope texture FAMILY a tile belongs to (ci-72bw): "cracks" (main line), "folds"
-- (the branch), or nil for every tile outside the branch span (including ash-dark, the
-- shared convergence, which belongs to NEITHER family precisely because both reach it).
function M.tile_branch(name) return TILE_BRANCH[name] end

-- The set of cindra tile names in a hot-slope family.
function M.family_tiles(branch)
  local out = {}
  for name, b in pairs(TILE_BRANCH) do if b == branch then out[name] = true end end
  return out
end

function M.is_walkable(name)
  local t = TILE_BY_NAME[name]
  if t == nil then return nil end
  return t.walkable
end

-- ---------------------------------------------------------------------------
-- value -> TILE damage (ci-ma18): the environmental damage a CONCRETE tile deals to
-- an entity standing on it. This is the TILE-BASED counterpart to M.value_damage --
-- the runtime sweep (scripts/tile-damage.lua) and the feedback tint
-- (scripts/damage-feedback.lua) read the ACTUAL tile under an entity, not a raw
-- position, so:
--   * a player-placed COVER tile (concrete / refined-concrete / stone-path -- any
--     tile that is NOT one of our value-ramp naturals) shields: it is absent from
--     VALUE_BAND, so it deals ZERO damage. Standing on concrete-over-lava is safe.
--   * every natural HAZARD tile burns/freezes wherever it renders: a hot crack or a
--     lava tile the noise scattered a little off its nominal band still damages,
--     because the TILE decides, not a positional band -- so no cosmetically-hot tile
--     ever reads safe (the ci-ma18 symptom the position model shipped).
--
-- NO CORRIDOR (why tile-based is safe again): the damaging naturals are exactly the
-- value-ramp tiles whose band crosses a threshold, and because the field is monotonic
-- those tiles form two contiguous EDGE BELTS -- there is no ridge of non-damaging
-- naturals reaching an ocean. A concrete cover can never bridge a zero-damage path to
-- either ocean either, because every ocean-gating hazard (lava/hot-crust + smooth/
-- rough ice) is in M.NO_PAVE, so paving over it is reverted (scripts/no-paving.lua).
-- (This is what the ci-oe83 "position-keyed" rewrite got wrong: it decoupled damage
-- from the tile to close the OLD three-heightmap corridor, but the ribbon is now ONE
-- monotonic heightmap, so the tile IS a safe corridor-proof key.)
--
-- A tile is as lethal as the MOST EXTREME value its band represents (heat peaks at the
-- band's hot bound, cold at its cold bound), so a threshold-edge hazard whose band
-- only just enters the damaging range (e.g. glowing cracks-hot at HOT_DMG) still burns.
function M.tile_damage(name)
  local vb = VALUE_BAND[name]
  if not vb then return 0, nil end -- a cover tile / soil overlay / unknown: shields
  local hi_i, hi_k = M.value_damage(vb.hi) -- the tile's hottest represented value
  local lo_i, lo_k = M.value_damage(vb.lo) -- the tile's coldest represented value
  local i, k = hi_i, hi_k
  if lo_i > hi_i then i, k = lo_i, lo_k end
  -- A safe-band tile whose band only touches a threshold (value_damage kind but
  -- intensity 0, e.g. cracks-warm at HOT_DMG) is SAFE: drop the phantom kind.
  if i <= 0 then return 0, nil end
  return i, k
end

function M.tile_names()
  local out = {}
  for _, t in ipairs(M.TILES) do out[#out + 1] = t.name end
  return out
end

-- The set of ramp tiles the ground can be painted with between two field VALUES: every
-- ramp member (both hot-slope families included) whose value band overlaps [h_lo, h_hi].
-- The value-space counterpart of M.zone_tiles below, which asks the same question for a
-- POSITION band. Ground clutter gated on a value segment (the rock/crater decals) reads
-- this to name the tiles it may sit on, and its tests read it to prove it did.
function M.value_range_tiles(h_lo, h_hi)
  local out = {}
  for name, vb in pairs(VALUE_BAND) do
    if vb.hi > h_lo and vb.lo < h_hi then out[name] = true end
  end
  return out
end

-- The Cindra tiles whose GROUND does `kind` damage ("heat" / "cold"), or -- with kind
-- nil -- the tiles that do none. Derived from M.tile_damage, so it tracks the value
-- ramp instead of restating it, and a retuned band moves these lists with it.
--
-- Exists so a placement rule can be keyed to the TILE rather than to a position
-- (ci-w87). Positions and tiles do not agree near a band edge: the bands are drawn
-- with a boundary wiggle plus a per-tile speckle in FIELD units, and where the field's
-- slope is gentle that speckle is worth several tiles of bleed -- glowing crust turns
-- up a good six tiles warmward of the nominal heat boundary. Anything that must LOOK
-- consistent with the ground (a rock model that says "this burns") therefore has to
-- read the tile, not the coordinate.
function M.tiles_by_damage(kind)
  local out = {}
  for _, name in ipairs(M.tile_names()) do
    local intensity, k = M.tile_damage(name)
    if kind == nil then
      if intensity <= 0 then out[#out + 1] = name end
    elseif intensity > 0 and k == kind then
      out[#out + 1] = name
    end
  end
  return out
end

-- The set of value-ramp member tiles a zone's perpendicular band can be painted with: the
-- ramp tiles whose value band overlaps the field's value range across that band (+ the
-- soil overlay in the middle). Used by tests + art helpers that ask "what can paint here".
function M.zone_tiles(role)
  local out = {}
  local band
  for _, z in ipairs(M.ZONES) do if z.role == role then band = M.role_band(role) end end
  if not band then return out end
  local h_lo = M.field(band.lo)
  local h_hi = M.field(band.hi)
  if h_lo > h_hi then h_lo, h_hi = h_hi, h_lo end
  out = M.value_range_tiles(h_lo, h_hi)
  if role == M.BUILDING_ROLE then
    for _, r in ipairs(M.SOIL_RING_ORDER) do out[cindra_name(r.vanilla)] = true end
  end
  return out
end

function M.tile_zones(name)
  local out = {}
  for _, z in ipairs(M.ZONES) do
    if M.zone_tiles(z.role)[name] then out[z.role] = true end
  end
  return out
end

-- ---------------------------------------------------------------------------
-- Noise tuning. The field contours are perturbed by a boundary WIGGLE that shifts the
-- perpendicular coordinate in TILES (so contours read organic), plus a small per-tile
-- SPECKLE in H units that breaks ties so co-present value bands interpenetrate at their
-- boundary. NOISE_AMPLITUDE / SPECKLE_AMPLITUDE (tile-space) stay the ci-fb9/ci-4iw
-- resource keep-back reads (scripts/resource-field.lua derives its damage margin from the
-- worst-case tile bleed = NOISE_AMPLITUDE + SPECKLE_AMPLITUDE); keeping them small keeps
-- damage tiles from bleeding into the resource band.
-- ---------------------------------------------------------------------------
M.NOISE_AMPLITUDE = 2    -- tiles: the boundary wiggle amplitude (also the resource margin)
M.NOISE_WAVELENGTH = 14
M.SPECKLE_AMPLITUDE = 1.5 -- tiles: nominal speckle bleed the resource margin budgets for
M.SPECKLE_H = 0.012      -- H: the actual per-tile speckle amplitude in the value field
M.SPECKLE_WAVELENGTH = 4
M.SOIL_AMPLITUDE = 26
M.SOIL_WAVELENGTH = 22
M.SOIL_WIN = 1.25   -- an in-patch soil tile beats the ash tile (whose band peak is 1)
M.SOIL_SHARP = 0.12 -- how fast a soil ring falls off outside its patch band
M.SOIL_GATE = 0.15  -- per-tile position penalty confining soil to the middle band

-- The hot-slope BRANCH selector (ci-72bw). A LOW-frequency signed noise: where it is
-- positive the folds family paints, where negative the cracks family does. The penalty is
-- what each family pays in the OTHER family's regions -- it only ever demotes the loser
-- below the winner's band peak (1), so no third tile can steal the band. Near the zero
-- crossing the penalty vanishes, so the two families interpenetrate and the family
-- boundary reads organic instead of as a seam.
M.BRANCH_AMPLITUDE = 1
M.BRANCH_WAVELENGTH = 90 -- tiles: broad regions, not per-tile salt-and-pepper
M.BRANCH_PENALTY = 0.8
-- CONTAINMENT. The value bands alone leave the folds family a per-tile speckle's worth of
-- bleed past the slope (the same interpenetration the main line has at every band edge).
-- The main line may bleed -- it is the established look, and its tiles are already part of
-- every neighbouring region's tile set -- but the BRANCH must be purely additive to the
-- SAFE hot slope: no folds tile may surface in the habitable middle, on the cold side, or
-- as a new zero-damage tile out in the lethal heat belt. So the folds family also carries
-- a positional GATE: a per-tile penalty outside a containment band, steep enough that one
-- tile past a gate line swamps the entire speckle budget.
--
-- The gate reads the RAW perpendicular, NOT the wiggled one the field uses. A gate on the
-- wiggled coordinate cannot contain anything in world space -- the wiggle just carries the
-- tile back over the line.
--
-- Both gate lines clear the family's VISIBLE (wiggled) contours by BRANCH_GATE_MARGIN, so
-- neither ever cuts a straight edge into the art:
--   * middle-ward line, a few tiles INSIDE the slope: the folds family's lowest value band
--     only begins ~12 tiles further out (where the field reaches BRANCH_SPAN.lo), so there
--     is nothing there to cut -- but the line still bites AT the slope edge itself.
--   * hot line, a few tiles OUTSIDE the slope: the family's top value band ends exactly at
--     the slope's hot edge, so the line sits past the wiggled folds/crust contour.
M.BRANCH_ROLE = "hot_outer" -- the zone band the folds family is contained to
M.BRANCH_GATE = 1.0         -- per-tile position penalty outside the containment band
M.BRANCH_GATE_MARGIN = 4    -- tiles of clearance between a gate line and the contour it must not clip

-- The perpendicular band the folds family is gated to (see above): the slope band with
-- each line pushed clear of the contour it must not clip.
function M.branch_gate_band(cfg)
  local slope = M.role_band(M.BRANCH_ROLE, cfg)
  return { lo = slope.lo + M.BRANCH_GATE_MARGIN, hi = slope.hi + M.BRANCH_GATE_MARGIN }
end

-- ---------------------------------------------------------------------------
-- Noise-expression emitters.
-- ---------------------------------------------------------------------------
local function num(v)
  if v == math.floor(v) then return string.format("%d", v) end
  return string.format("%.6g", v)
end

local function basis(seed1, amp, wl)
  return "basis_noise{x = x, y = y, seed0 = 1, seed1 = " .. num(seed1) ..
         ", input_scale = " .. num(1 / wl) .. ", output_scale = " .. num(amp) .. "}"
end
local function wiggle_noise() return basis(7, M.NOISE_AMPLITUDE, M.NOISE_WAVELENGTH) end
local function speckle_noise(tile_index) return basis(100 + tile_index, M.SPECKLE_H, M.SPECKLE_WAVELENGTH) end
local function branch_noise() return basis(60, M.BRANCH_AMPLITUDE, M.BRANCH_WAVELENGTH) end

local function relu(expr) return "max(0, " .. expr .. ")" end
local function clamp01(expr) return "min(1, max(0, " .. expr .. "))" end

-- The FIELD as a noise-expression string over the wiggled perpendicular coordinate `Pexpr`.
-- Builds the same monotonic PWL as pwl() from the cumulative slope changes:
--   H(P) = h0 + Σ (slope_i - slope_{i-1}) * relu(P - p_i)
-- clamped to [0, 1]. This is the ONE field the map-gen paints from.
local function field_expr(Pexpr, anchors)
  local expr = num(anchors[1].h)
  local prev_slope = 0
  for i = 1, #anchors - 1 do
    local a, b = anchors[i], anchors[i + 1]
    local slope = (b.h - a.h) / (b.p - a.p)
    local d = slope - prev_slope
    expr = expr .. " + " .. num(d) .. " * " .. relu(Pexpr .. " - " .. num(a.p))
    prev_slope = slope
  end
  return clamp01("(" .. expr .. ")")
end

-- One VALUE-BAND term for a ramp tile: peaks at 1 where the field value Hf is inside the
-- tile's band [lo, hi], falling off outside it. The engine places the highest-probability
-- tile per point, so the tile whose band contains Hf wins -> concentric value contours.
local function value_band_term(band, Hf)
  return "(1 - (" .. relu(num(band.lo) .. " - " .. Hf) ..
         " + " .. relu(Hf .. " - " .. num(band.hi)) .. "))"
end

-- The BRANCH penalty a hot-slope family member pays outside its own regions (ci-72bw).
-- The folds family is gated to branch-noise > 0, the cracks family to branch-noise < 0;
-- both fall to zero penalty at the crossing, so neither family has a hard edge.
local function branch_term(branch, cfg)
  local B = branch_noise()
  local losing = (branch == "folds") and relu("-(" .. B .. ")") or relu(B)
  local expr = " - " .. num(M.BRANCH_PENALTY) .. " * " .. losing
  if branch == "folds" then
    local g = M.branch_gate_band(cfg)
    local perp = axis.perp_expr()
    expr = expr .. " - " .. num(M.BRANCH_GATE) .. " * (" ..
           relu(num(g.lo) .. " - " .. perp) .. " + " .. relu(perp .. " - " .. num(g.hi)) .. ")"
  end
  return expr
end

-- One SOIL patch term: an OVERLAY that wins over the ash tiles only inside a patch of the
-- low-frequency soil field AND only in the middle band (a positional gate). SOIL_WIN puts
-- an in-patch soil ring above the ash band peak (1); the gate + the ring falloff drop it
-- below 1 outside the patch / outside the middle, so ash wins everywhere else.
local function soil_term(Pexpr, mid_band, band)
  local gate = num(M.SOIL_GATE) .. " * (" ..
               relu(num(mid_band.lo) .. " - " .. Pexpr) .. " + " ..
               relu(Pexpr .. " - " .. num(mid_band.hi)) .. ")"
  local E = basis(50, M.SOIL_AMPLITUDE, M.SOIL_WAVELENGTH)
  local ring = num(M.SOIL_SHARP) .. " * (" .. relu(num(band.lo) .. " - " .. E) ..
               " + " .. relu(E .. " - " .. num(band.hi)) .. ")"
  return "(" .. num(M.SOIL_WIN) .. " - " .. ring .. " - " .. gate .. ")"
end

-- The `probability_expression` for a Cindra tile: its value-band term (or soil overlay
-- term) + a per-tile speckle so co-present bands interpenetrate at their boundary. The
-- field is sampled on the WIGGLED perpendicular coordinate so the contours read organic.
function M.probability_expr(name, cfg)
  local tile, index
  for i, t in ipairs(M.TILES) do
    if t.name == name then tile = t; index = i; break end
  end
  if not tile then error("terrain: unknown Cindra tile " .. tostring(name)) end

  local anchors = M.field_anchors(cfg)
  local P = "(" .. axis.perp_expr() .. " + " .. wiggle_noise() .. ")"
  local Hf = field_expr(P, anchors)

  local term
  local vb = VALUE_BAND[name]
  if vb then
    term = value_band_term(vb, Hf)
    -- Hot-slope family members additionally pay the branch penalty outside their regions.
    local branch = TILE_BRANCH[name]
    if branch then term = "(" .. term .. branch_term(branch, cfg) .. ")" end
  else
    local sband = SOIL_RING_BAND[name]
    if not sband then error("terrain: tile " .. name .. " has no placement term") end
    term = soil_term(P, M.role_band(M.BUILDING_ROLE, cfg), sband)
  end
  return "(" .. term .. ") + " .. speckle_noise(index)
end

-- The map-gen key that bounds the ribbon's PERPENDICULAR (hot-cold) axis, and the
-- total ribbon width to bound it at. Vertical bands on X -> "width"; horizontal
-- bands on Y -> "height".
function M.finite_dimension(cfg)
  local _, total = M.bands(cfg)
  return {
    key = (axis.orientation() == axis.HORIZONTAL) and "height" or "width",
    value = total,
  }
end

-- The map-gen key of the ribbon's LONG axis: the one that must stay INFINITE.
function M.infinite_dimension_key()
  return (axis.orientation() == axis.HORIZONTAL) and "width" or "height"
end

-- The map-gen bounds for BOTH world axes. A ribbon is bounded on exactly ONE axis,
-- so this states the long axis explicitly as 0 (= infinite in Factorio) rather than
-- leaving it to whatever the surface already carried. Setting only the finite key
-- is what broke the horizontal ribbon (ci-65p): a surface whose OTHER axis was
-- already bounded -- a world generated under the other orientation, or any settings
-- source that carries a size -- kept that bound and boxed the player in on both
-- axes, which is a rectangle, not a ribbon.
function M.map_gen_bounds(cfg)
  local finite = M.finite_dimension(cfg)
  local bounds = { width = 0, height = 0 }
  bounds[finite.key] = finite.value
  return bounds
end

return M
